#!/bin/bash
# Complete deployment script with embedded base64 data

set -e

echo "Deploying BEN Admin UI via base64..."

# Create admin-ui directory structure
sudo mkdir -p /var/www/signaturebrain/admin-ui/assets

echo "Decoding and deploying index.html..."
cat << 'EOF_HTML' | base64 -d | sudo tee /var/www/signaturebrain/admin-ui/index.html > /dev/null
_HTML

echo "Decoding and deploying CSS..."
cat << 'EOF_CSS' | base64 -d | sudo tee /var/www/signaturebrain/admin-ui/assets/index-ZEVQuCWO.css > /dev/null
_CSS

echo "Decoding and deploying JavaScript (this may take a moment)..."
cat << 'EOF_JS' | base64 -d | sudo tee /var/www/signaturebrain/admin-ui/assets/index-BTkehRqw.js > /dev/null
_JS

# Set proper permissions
echo "Setting permissions..."
sudo chown -R www-data:www-data /var/www/signaturebrain/admin-ui
sudo chmod -R 755 /var/www/signaturebrain/admin-ui
sudo chmod 644 /var/www/signaturebrain/admin-ui/index.html
sudo chmod 644 /var/www/signaturebrain/admin-ui/assets/*

# Verify files
echo ""
echo "Verifying deployment..."
ls -lh /var/www/signaturebrain/admin-ui/
ls -lh /var/www/signaturebrain/admin-ui/assets/

# Test and reload nginx
echo ""
echo "Testing Nginx configuration..."
sudo nginx -t

echo "Reloading Nginx..."
sudo systemctl reload nginx

echo ""
echo "✅ Deployment complete!"
echo ""
echo "Admin UI deployed to: http://signaturebrain.com/admin"
echo ""
echo "File sizes deployed:"
echo "  - index.html: $(stat -c%s /var/www/signaturebrain/admin-ui/index.html) bytes"
echo "  - CSS: $(stat -c%s /var/www/signaturebrain/admin-ui/assets/index-ZEVQuCWO.css) bytes"
echo "  - JavaScript: $(stat -c%s /var/www/signaturebrain/admin-ui/assets/index-BTkehRqw.js) bytes"
echo ""
echo "⚠️  IMPORTANT: Hard refresh your browser (Ctrl+Shift+R or Cmd+Shift+R)"
echo "   Or clear site data to bypass cache and see the new UI!"
echo ""
